def mode(numbers: List[float]) -> float:
    """ For a given list of input numbers, return the mode.
    The mode is the number that appears most frequently in a list of numbers.
    If there is more than one number that repeats the most often, one of them will be returned.
    The list will contain only numbers, either positive, negative or zero, and there will be no zero as a
    mode if this is the case.
    >>> mode([1, 2, 2, 2, 4, 5, 6])
    2
    >>> mode([1, 1, 2, 3, 5, 5])
    5
    """
    if not numbers:
        raise ValueError("Empty List")
    count_dict = {}
    for number in numbers:
        if number in count_dict:
            count_dict[number] += 1
        else:
            count_dict[number] = 1

    return max(count_dict, key=count_dict.get)


