def filter_by_string_length(strings: List[str], min_length: int, max_length: int) -> List[str]:
    """ Filter an input list of strings only for those of the given string length
    >>> filter_by_string_length([], 1, 10)
    []
    >>> filter_by_string_length(['abc', 'abcde', 'array'], 2, 5)
    ['abc', 'array']
    """
    return list(filter(lambda x: min_length <= len(x) <= max_length, strings))

