def power(base: float, exponent: int) -> float:
    """ Given two positive floating point numbers, return base^exponent, where
    exponent is the number of times base is added to itself.
    >>> power(2, 2)
    4
    >>> power(2, 0)
    1
    """
    if (exponent == 0):
        return 1
    else:
        return base * power(base, exponent - 1)


def power_recursive(base: float, exponent: int) -> float:
    """Given two positive floating point numbers, return base^exponent, where
    exponent is the number of times base is added to itself.
    >>> power_recursive(2, 2)
    4
    >>> power_recursive(2, 0)
    1
    """
    if (exponent == 0):
        return 1
    else:
        return base * power_recursive(base, exponent - 1)

