def nesting(paren_string: str) -> int:
    """ Input to this function is a string of parentheses, open or close.
    The goal is to count the deepest level of nesting using only open and close
    characters in the string.

    >>> nesting('()(((())))')
    4
    >>> nesting('()))))())')
    2
    """
    stack = []
    for i in paren_string:
        if i in '([{':
            stack.append(i)
        if i in ')]}':
            if not stack:
                return 0
            if i in ')]}':
                if (stack[-1] == '(' and i == ')') or (stack[-1] == '{' and i == '}') or (stack[-1] == '[' and i == ']'):
                    stack.pop()
                else:
                    return 0
            else:
                return 0
    return len(stack)

