    """ Given a list l, return True if there are two distinct elements with same value
    and False otherwise. Use only O(1) extra space.
    >>> contains_dups([])
    False
    >>> contains_dups([1, 2, 3, 4, 5])
    False
    >>> contains_dups([1, 1, 2, 2, 3])
    True
    """
    freq = {}
    for v in l:
        if v in freq:
            return True
        else:
            freq[v] = 0
    return False


