def mean_absolute_percentage_error(y_true: List[float], y_pred: List[float]) -> float:
    """ For a given dataset, calculate Mean Absolute Percentage Error around
    the mean of this dataset.
    Mean Absolute Percentage Error is:
    MAPE = (1/N) * sum(|y_true[i] - y_pred[i]/y_true[i] * 100| for i in 0..N-1)
    """
    if not y_true and not y_pred:
        return 0.0
    center = sum(y_true) / len(y_true)
    sum_error = 0
    for t, p in zip(y_true, y_pred):
        if t == 0 and p == 0:
            continue
        sum_error += abs((t - p)/center)
    return sum_error / len(y_true)


